  public var CANDIDATE_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CANDIDATE_ID) }
  ///  Ordered encounters, first to last.
  public var ENCOUNTERS: FlatbufferVector<MDSEncounter> { return _accessor.vector(at: VT.ENCOUNTERS, byteSize: 4) }
  ///  Deep-space maneuvers, ordered by LEG_INDEX then ARC_FRACTION.
  public var DEEP_SPACE_MANEUVERS: FlatbufferVector<MDSDeepSpaceManeuver> { return _accessor.vector(at: VT.DEEP_SPACE_MANEUVERS, byteSize: 4) }
  ///  Total post-launch delta-V, km/s.
  public var TOTAL_DELTA_V_KM_S: Double { let o = _accessor.offset(VT.TOTAL_DELTA_V_KM_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Total flight time from first to last encounter, days.
  public var TOTAL_FLIGHT_TIME_DAYS: Double { let o = _accessor.offset(VT.TOTAL_FLIGHT_TIME_DAYS); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Launch characteristic energy, km^2/s^2.
  public var LAUNCH_C3_KM2_S2: Double { let o = _accessor.offset(VT.LAUNCH_C3_KM2_S2); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Hyperbolic excess speed at arrival, km/s.
  public var ARRIVAL_V_INFINITY_KM_S: Double { let o = _accessor.offset(VT.ARRIVAL_V_INFINITY_KM_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Reference escape delta-V from the departure body, km/s.
  public var ESCAPE_DELTA_V_KM_S: Double { let o = _accessor.offset(VT.ESCAPE_DELTA_V_KM_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Reference insertion delta-V at the arrival body, km/s.
  public var INSERTION_DELTA_V_KM_S: Double { let o = _accessor.offset(VT.INSERTION_DELTA_V_KM_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  True when this candidate is non-dominated within the set. A set MAY carry
  ///  dominated candidates for context; a consumer plotting a front MUST filter
  ///  on this rather than assume every member is non-dominated.
  public var NON_DOMINATED: Bool { let o = _accessor.offset(VT.NON_DOMINATED); return o == 0 ? true : _accessor.readBuffer(of: Bool.self, at: o) }
  public static func startMDSCandidate(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 10) }
  public static func add(CANDIDATE_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CANDIDATE_ID, at: VT.CANDIDATE_ID) }
  public static func addVectorOf(ENCOUNTERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ENCOUNTERS, at: VT.ENCOUNTERS) }
  public static func addVectorOf(DEEP_SPACE_MANEUVERS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DEEP_SPACE_MANEUVERS, at: VT.DEEP_SPACE_MANEUVERS) }
  public static func add(TOTAL_DELTA_V_KM_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TOTAL_DELTA_V_KM_S, def: 0.0, at: VT.TOTAL_DELTA_V_KM_S) }
  public static func add(TOTAL_FLIGHT_TIME_DAYS: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TOTAL_FLIGHT_TIME_DAYS, def: 0.0, at: VT.TOTAL_FLIGHT_TIME_DAYS) }
  public static func add(LAUNCH_C3_KM2_S2: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: LAUNCH_C3_KM2_S2, def: 0.0, at: VT.LAUNCH_C3_KM2_S2) }
  public static func add(ARRIVAL_V_INFINITY_KM_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ARRIVAL_V_INFINITY_KM_S, def: 0.0, at: VT.ARRIVAL_V_INFINITY_KM_S) }
  public static func add(ESCAPE_DELTA_V_KM_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ESCAPE_DELTA_V_KM_S, def: 0.0, at: VT.ESCAPE_DELTA_V_KM_S) }
  public static func add(INSERTION_DELTA_V_KM_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: INSERTION_DELTA_V_KM_S, def: 0.0, at: VT.INSERTION_DELTA_V_KM_S) }
  public static func add(NON_DOMINATED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: NON_DOMINATED, def: true,
   at: VT.NON_DOMINATED) }
  public static func endMDSCandidate(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createMDSCandidate(
    _ fbb: inout FlatBufferBuilder,
    CANDIDATE_IDOffset CANDIDATE_ID: Offset = Offset(),
    ENCOUNTERSVectorOffset ENCOUNTERS: Offset = Offset(),
    DEEP_SPACE_MANEUVERSVectorOffset DEEP_SPACE_MANEUVERS: Offset = Offset(),
    TOTAL_DELTA_V_KM_S: Double = 0.0,
    TOTAL_FLIGHT_TIME_DAYS: Double = 0.0,
    LAUNCH_C3_KM2_S2: Double = 0.0,
    ARRIVAL_V_INFINITY_KM_S: Double = 0.0,
    ESCAPE_DELTA_V_KM_S: Double = 0.0,
    INSERTION_DELTA_V_KM_S: Double = 0.0,
    NON_DOMINATED: Bool = true
  ) -> Offset {
    let __start = MDSCandidate.startMDSCandidate(&fbb)
    MDSCandidate.add(CANDIDATE_ID: CANDIDATE_ID, &fbb)
    MDSCandidate.addVectorOf(ENCOUNTERS: ENCOUNTERS, &fbb)
    MDSCandidate.addVectorOf(DEEP_SPACE_MANEUVERS: DEEP_SPACE_MANEUVERS, &fbb)
    MDSCandidate.add(TOTAL_DELTA_V_KM_S: TOTAL_DELTA_V_KM_S, &fbb)
    MDSCandidate.add(TOTAL_FLIGHT_TIME_DAYS: TOTAL_FLIGHT_TIME_DAYS, &fbb)
    MDSCandidate.add(LAUNCH_C3_KM2_S2: LAUNCH_C3_KM2_S2, &fbb)
    MDSCandidate.add(ARRIVAL_V_INFINITY_KM_S: ARRIVAL_V_INFINITY_KM_S, &fbb)
    MDSCandidate.add(ESCAPE_DELTA_V_KM_S: ESCAPE_DELTA_V_KM_S, &fbb)
    MDSCandidate.add(INSERTION_DELTA_V_KM_S: INSERTION_DELTA_V_KM_S, &fbb)
    MDSCandidate.add(NON_DOMINATED: NON_DOMINATED, &fbb)
    return MDSCandidate.endMDSCandidate(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.CANDIDATE_ID, fieldName: "CANDIDATE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ENCOUNTERS, fieldName: "ENCOUNTERS", required: false, type: ForwardOffset<Vector<ForwardOffset<MDSEncounter>, MDSEncounter>>.self)
    try _v.visit(field: VT.DEEP_SPACE_MANEUVERS, fieldName: "DEEP_SPACE_MANEUVERS", required: false, type: ForwardOffset<Vector<ForwardOffset<MDSDeepSpaceManeuver>, MDSDeepSpaceManeuver>>.self)
    try _v.visit(field: VT.TOTAL_DELTA_V_KM_S, fieldName: "TOTAL_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.TOTAL_FLIGHT_TIME_DAYS, fieldName: "TOTAL_FLIGHT_TIME_DAYS", required: false, type: Double.self)
    try _v.visit(field: VT.LAUNCH_C3_KM2_S2, fieldName: "LAUNCH_C3_KM2_S2", required: false, type: Double.self)
    try _v.visit(field: VT.ARRIVAL_V_INFINITY_KM_S, fieldName: "ARRIVAL_V_INFINITY_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.ESCAPE_DELTA_V_KM_S, fieldName: "ESCAPE_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.INSERTION_DELTA_V_KM_S, fieldName: "INSERTION_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.NON_DOMINATED, fieldName: "NON_DOMINATED", required: false, type: Bool.self)
    _v.finish()
  }
}

///  Mission Design Solution Set — a set of candidate trajectories produced by
///  solving a mission design broad search, typically a Pareto front over
///  competing objectives (total delta-V against total flight time).
///
///  SDS had no multi-candidate container of any kind before this record. The
///  closest existing carrier for a single planned burn is OCM.Maneuver, whose
///  payload is untyped DATA:[string] with MAN_UNITS:[string] and which has no
///  v-infinity, turn angle, flyby periapsis radius, or C3.
public struct MDS: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MDS" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: MDS.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let SOLUTION_SET_ID: VOffset = 4
    static let PROBLEM_ID: VOffset = 6
    static let OBJECTIVES: VOffset = 8
    static let CANDIDATES: VOffset = 10
    static let SOLVER: VOffset = 12
    static let SOLVER_VERSION: VOffset = 14
    static let EPHEMERIS_SOURCE: VOffset = 16
    static let CREATION_DATE: VOffset = 18
    static let COMMENT: VOffset = 20
  }

  ///  Stable identifier for this solution set.
  public var SOLUTION_SET_ID: String! { let o = _accessor.offset(VT.SOLUTION_SET_ID); return _accessor.string(at: o) }
  public var SOLUTION_SET_IDSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.SOLUTION_SET_ID) }
  ///  PROBLEM_ID of the $MDP this set solves. A solution set whose problem
  ///  definition is unknown is not reproducible.
  public var PROBLEM_ID: String? { let o = _accessor.offset(VT.PROBLEM_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var PROBLEM_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PROBLEM_ID) }
  ///  Objectives the front is expressed over, e.g.
  ///  ["TOTAL_DELTA_V_KM_S", "TOTAL_FLIGHT_TIME_DAYS"]. Names MUST be field
  ///  names of MDSCandidate.
  public var OBJECTIVES: FlatbufferVector<String?> { return _accessor.vector(at: VT.OBJECTIVES, byteSize: 4) }
  ///  The candidates.
  public var CANDIDATES: FlatbufferVector<MDSCandidate> { return _accessor.vector(at: VT.CANDIDATES, byteSize: 4) }
  ///  Solver identity and version that produced the set.
  public var SOLVER: String? { let o = _accessor.offset(VT.SOLVER); return o == 0 ? nil : _accessor.string(at: o) }
  public var SOLVERSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SOLVER) }
  public var SOLVER_VERSION: String? { let o = _accessor.offset(VT.SOLVER_VERSION); return o == 0 ? nil : _accessor.string(at: o) }
  public var SOLVER_VERSIONSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SOLVER_VERSION) }
  ///  Ephemeris source used, e.g. a SPICE kernel set identifier.
  public var EPHEMERIS_SOURCE: String? { let o = _accessor.offset(VT.EPHEMERIS_SOURCE); return o == 0 ? nil : _accessor.string(at: o) }
  public var EPHEMERIS_SOURCESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.EPHEMERIS_SOURCE) }
  ///  When the set was generated, ISO 8601.
  public var CREATION_DATE: String? { let o = _accessor.offset(VT.CREATION_DATE); return o == 0 ? nil : _accessor.string(at: o) }
  public var CREATION_DATESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CREATION_DATE) }
  ///  Free-form notes.
  public var COMMENT: String? { let o = _accessor.offset(VT.COMMENT); return o == 0 ? nil : _accessor.string(at: o) }
  public var COMMENTSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.COMMENT) }
  public static func startMDS(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 9) }
  public static func add(SOLUTION_SET_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOLUTION_SET_ID, at: VT.SOLUTION_SET_ID) }
  public static func add(PROBLEM_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROBLEM_ID, at: VT.PROBLEM_ID) }
  public static func addVectorOf(OBJECTIVES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OBJECTIVES, at: VT.OBJECTIVES) }
  public static func addVectorOf(CANDIDATES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CANDIDATES, at: VT.CANDIDATES) }
  public static func add(SOLVER: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOLVER, at: VT.SOLVER) }
  public static func add(SOLVER_VERSION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOLVER_VERSION, at: VT.SOLVER_VERSION) }
  public static func add(EPHEMERIS_SOURCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EPHEMERIS_SOURCE, at: VT.EPHEMERIS_SOURCE) }
  public static func add(CREATION_DATE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CREATION_DATE, at: VT.CREATION_DATE) }
  public static func add(COMMENT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: COMMENT, at: VT.COMMENT) }
  public static func endMDS(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4]); return end }
  public static func createMDS(
    _ fbb: inout FlatBufferBuilder,
    SOLUTION_SET_IDOffset SOLUTION_SET_ID: Offset,
    PROBLEM_IDOffset PROBLEM_ID: Offset = Offset(),
    OBJECTIVESVectorOffset OBJECTIVES: Offset = Offset(),
    CANDIDATESVectorOffset CANDIDATES: Offset = Offset(),
    SOLVEROffset SOLVER: Offset = Offset(),
    SOLVER_VERSIONOffset SOLVER_VERSION: Offset = Offset(),
    EPHEMERIS_SOURCEOffset EPHEMERIS_SOURCE: Offset = Offset(),
    CREATION_DATEOffset CREATION_DATE: Offset = Offset(),
    COMMENTOffset COMMENT: Offset = Offset()
  ) -> Offset {
    let __start = MDS.startMDS(&fbb)
    MDS.add(SOLUTION_SET_ID: SOLUTION_SET_ID, &fbb)
    MDS.add(PROBLEM_ID: PROBLEM_ID, &fbb)
    MDS.addVectorOf(OBJECTIVES: OBJECTIVES, &fbb)
    MDS.addVectorOf(CANDIDATES: CANDIDATES, &fbb)
    MDS.add(SOLVER: SOLVER, &fbb)
    MDS.add(SOLVER_VERSION: SOLVER_VERSION, &fbb)
    MDS.add(EPHEMERIS_SOURCE: EPHEMERIS_SOURCE, &fbb)
    MDS.add(CREATION_DATE: CREATION_DATE, &fbb)
    MDS.add(COMMENT: COMMENT, &fbb)
    return MDS.endMDS(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.SOLUTION_SET_ID, fieldName: "SOLUTION_SET_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROBLEM_ID, fieldName: "PROBLEM_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.OBJECTIVES, fieldName: "OBJECTIVES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.CANDIDATES, fieldName: "CANDIDATES", required: false, type: ForwardOffset<Vector<ForwardOffset<MDSCandidate>, MDSCandidate>>.self)
    try _v.visit(field: VT.SOLVER, fieldName: "SOLVER", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOLVER_VERSION, fieldName: "SOLVER_VERSION", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.EPHEMERIS_SOURCE, fieldName: "EPHEMERIS_SOURCE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CREATION_DATE, fieldName: "CREATION_DATE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COMMENT, fieldName: "COMMENT", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}
